<?php
namespace App\Services;

use App\Events\DomainRealtimeEvent;
use App\Models\{CoupleMember,Memory};
use App\Support\{ApiResponse,RequestContext};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;

class RelationshipDomainService
{
    private array $supported=['pings','pings.reactions','widgets.ping','goals','bucket-list','bucket-list.convert-to-milestone','long-distance','moods','need-you','shared-lists.items','migrations.device'];
    public function supports(string $r):bool{return in_array($r,$this->supported,true);}
    public function handle(string $op,string $resource,Request $r){return match(true){in_array($resource,['pings','pings.reactions','widgets.ping'],true)=>$this->pings($op,$r),$resource==='goals'=>$this->goals($op,$r),str_starts_with($resource,'bucket-list')=>$this->bucket($op,$r),$resource==='long-distance'=>$this->longDistance($op,$r),$resource==='moods'=>$this->moods($op,$r),$resource==='need-you'=>$this->needYou($op,$r),$resource==='shared-lists.items'=>$this->sharedListItems($op,$r),$resource==='migrations.device'=>$this->deviceMigration($op,$r),default=>ApiResponse::problem('Unsupported relationship operation',$op,501,'not_implemented')};}

    private function pings(string $op,Request $r){$space=RequestContext::coupleSpaceId($r);if($op==='get_pings')return ApiResponse::ok(DB::table('pings')->where('couple_space_id',$space)->whereNull('deleted_at')->latest()->limit(min((int)$r->input('limit',50),100))->get()->map(fn($x)=>$this->decode($x)));if(str_contains($op,'reactions')){$id=$r->route('pingId');$d=$r->validate(['reaction'=>'required|string|max:80']);$row=$this->decode(DB::table('pings')->where('id',$id)->where('couple_space_id',$space)->first());if(!$row)return ApiResponse::problem('Ping not found','Ping does not exist.',404,'not_found');$data=$row['data']??[];$data['reactions'][$r->user()->id]=$d['reaction'];DB::table('pings')->where('id',$id)->update(['data'=>json_encode($data),'updated_at'=>now()]);event(new DomainRealtimeEvent('ping.reacted',['ping_id'=>$id,'user_id'=>$r->user()->id,'reaction'=>$d['reaction']],null,$space));return ApiResponse::ok(['reacted'=>true]);}$id=(string)Str::uuid();DB::table('pings')->insert($this->row($r,['id'=>$id,'type'=>'romantic_ping','status'=>'sent','data'=>json_encode($r->all())]));event(new DomainRealtimeEvent('ping.received',['ping_id'=>$id,'from_user_id'=>$r->user()->id],null,$space));return ApiResponse::created($this->decode(DB::table('pings')->where('id',$id)->first()));}

    private function goals(string $op,Request $r){$space=RequestContext::coupleSpaceId($r);$goalId=$r->route('goalId');if(str_contains($op,'progress')){$d=$r->validate(['value'=>'required|numeric','note'=>'nullable|string|max:2000']);$id=(string)Str::uuid();DB::table('goal_progress')->insert($this->row($r,['id'=>$id,'parent_id'=>$goalId,'type'=>'progress','data'=>json_encode($d)]));event(new DomainRealtimeEvent('goal.progress.updated',['goal_id'=>$goalId,'progress'=>$d],null,$space));return ApiResponse::created($this->decode(DB::table('goal_progress')->where('id',$id)->first()));}if(str_contains($op,'comments')){$d=$r->validate(['body'=>'required|string|max:5000']);$id=(string)Str::uuid();DB::table('feature_records')->insert(['id'=>$id,'resource'=>'goal.comment','user_id'=>$r->user()->id,'couple_space_id'=>$space,'parent_id'=>$goalId,'status'=>'active','data'=>json_encode($d),'metadata'=>json_encode([]),'occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return ApiResponse::created(['id'=>$id]+$d);}return $this->crud('goals',$r);}

    private function bucket(string $op,Request $r){$space=RequestContext::coupleSpaceId($r);$id=$r->route('itemId');if(str_contains($op,'comments')){$d=$r->validate(['body'=>'required|string|max:5000']);$cid=(string)Str::uuid();DB::table('feature_records')->insert(['id'=>$cid,'resource'=>'bucket.comment','user_id'=>$r->user()->id,'couple_space_id'=>$space,'parent_id'=>$id,'status'=>'active','data'=>json_encode($d),'metadata'=>json_encode([]),'occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return ApiResponse::created(['id'=>$cid]+$d);}if(str_contains($op,'complete')){DB::table('bucket_items')->where('id',$id)->where('couple_space_id',$space)->update(['status'=>'completed','completed_at'=>now(),'updated_at'=>now()]);return ApiResponse::ok($this->decode(DB::table('bucket_items')->where('id',$id)->first()));}if(str_contains($op,'convert_to_milestone')){$item=$this->decode(DB::table('bucket_items')->where('id',$id)->where('couple_space_id',$space)->first());if(!$item)return ApiResponse::problem('Bucket item not found','Bucket item does not exist.',404,'not_found');$m=Memory::create(['couple_space_id'=>$space,'user_id'=>$r->user()->id,'type'=>'milestone','title'=>$item['title']??'Bucket List Milestone','content'=>['bucket_item_id'=>$id,'item'=>$item['data']??[]],'tags'=>['bucket-list'],'is_draft'=>false,'is_locked'=>false]);return ApiResponse::created($m);}return $this->crud('bucket_items',$r);}

    private function longDistance(string $op,Request $r){$space=RequestContext::coupleSpaceId($r);$row=$this->decode(DB::table('long_distance_settings')->where('couple_space_id',$space)->whereNull('deleted_at')->latest()->first());if($op==='get_long_distance_partner_time'){$partner=CoupleMember::where('couple_space_id',$space)->where('user_id','!=',$r->user()->id)->with('user')->first()?->user;if(!$partner)return ApiResponse::ok(null);try{$time=now($partner->timezone?:'UTC')->toIso8601String();}catch(\Throwable){$time=now('UTC')->toIso8601String();}return ApiResponse::ok(['timezone'=>$partner->timezone,'local_time'=>$time]);}if($op==='get_long_distance_distance')return ApiResponse::ok(['distance_km'=>data_get($row,'data.distance_km'),'source'=>'client/location-session-derived']);if($op==='get_long_distance_next_meet')return ApiResponse::ok(data_get($row,'data.next_meet'));if($op==='put_long_distance_next_meet'){$d=$r->validate(['next_meet'=>'required|date']);$data=$row['data']??[];$data['next_meet']=$d['next_meet'];return $this->upsertSetting('long_distance_settings',$r,$data);}if($r->method()==='GET')return ApiResponse::ok($row);$data=array_replace_recursive($row['data']??[],$r->all());return $this->upsertSetting('long_distance_settings',$r,$data);}

    private function moods(string $op,Request $r){$space=RequestContext::coupleSpaceId($r);if($op==='get_moods_current')return ApiResponse::ok($this->decode(DB::table('moods')->where('user_id',$r->user()->id)->whereNull('deleted_at')->latest()->first()));if($op==='get_moods')return ApiResponse::ok(DB::table('moods')->where('couple_space_id',$space)->whereNull('deleted_at')->latest()->limit(100)->get()->map(fn($x)=>$this->decode($x)));if($op==='patch_moods_privacy'){$d=$r->validate(['shared'=>'required|boolean']);$prefs=$r->user()->privacy_permissions?:[];$prefs['mood_shared']=$d['shared'];$r->user()->update(['privacy_permissions'=>$prefs]);return ApiResponse::ok(['shared'=>$d['shared']]);}$d=$r->validate(['mood'=>'required|string|max:80','note'=>'nullable|string|max:500','visibility'=>'nullable|in:partner,private']);$id=(string)Str::uuid();DB::table('moods')->insert($this->row($r,['id'=>$id,'type'=>$d['mood'],'body'=>$d['note']??null,'data'=>json_encode(['visibility'=>$d['visibility']??'partner'])]));if(($d['visibility']??'partner')==='partner')event(new DomainRealtimeEvent('mood.updated',['mood'=>$d['mood'],'user_id'=>$r->user()->id],null,$space));return ApiResponse::created($this->decode(DB::table('moods')->where('id',$id)->first()));}

    private function needYou(string $op,Request $r){$space=RequestContext::coupleSpaceId($r);if(str_contains($op,'respond')){$id=$r->route('needYouId');$d=$r->validate(['response'=>'nullable|string|max:500']);DB::table('need_you_events')->where('id',$id)->where('couple_space_id',$space)->update(['status'=>'responded','body'=>$d['response']??"I'm here",'completed_at'=>now(),'updated_at'=>now()]);event(new DomainRealtimeEvent('need_you.responded',['id'=>$id,'user_id'=>$r->user()->id,'response'=>$d['response']??"I'm here"],null,$space));return ApiResponse::ok(['responded'=>true]);}$id=(string)Str::uuid();DB::table('need_you_events')->insert($this->row($r,['id'=>$id,'type'=>'need-you','status'=>'sent','data'=>json_encode($r->all())]));event(new DomainRealtimeEvent('need_you.received',['id'=>$id,'from_user_id'=>$r->user()->id],null,$space));return ApiResponse::created($this->decode(DB::table('need_you_events')->where('id',$id)->first()));}

    private function sharedListItems(string $op,Request $r){$space=RequestContext::coupleSpaceId($r);$listId=$r->route('listId');$itemId=$r->route('itemId');$list=DB::table('shared_lists')->where('id',$listId)->where('couple_space_id',$space)->whereNull('deleted_at')->first();if(!$list)return ApiResponse::problem('List not found','Shared list does not exist.',404,'not_found');if($r->method()==='GET')return ApiResponse::ok(DB::table('shared_list_items')->where('parent_id',$listId)->whereNull('deleted_at')->latest()->get()->map(fn($x)=>$this->decode($x)));if($r->method()==='DELETE'){DB::table('shared_list_items')->where('id',$itemId)->where('parent_id',$listId)->update(['deleted_at'=>now(),'updated_at'=>now()]);return ApiResponse::ok(['deleted'=>true]);}if($r->method()==='PATCH'){$old=$this->decode(DB::table('shared_list_items')->where('id',$itemId)->where('parent_id',$listId)->first());if(!$old)return ApiResponse::problem('Item not found','List item does not exist.',404,'not_found');$data=array_replace_recursive($old['data']??[],$r->all());DB::table('shared_list_items')->where('id',$itemId)->update(['title'=>$r->input('title',$old['title']??null),'status'=>$r->input('status',$old['status']??'active'),'data'=>json_encode($data),'updated_at'=>now()]);return ApiResponse::ok($this->decode(DB::table('shared_list_items')->where('id',$itemId)->first()));}$d=$r->validate(['title'=>'required|string|max:255','status'=>'nullable|in:want_to,planned,completed,favorite','type'=>'nullable|string|max:80','data'=>'nullable|array','secret_gift_marker'=>'nullable|boolean']);$id=(string)Str::uuid();DB::table('shared_list_items')->insert($this->row($r,['id'=>$id,'parent_id'=>$listId,'type'=>$d['type']??'item','title'=>$d['title'],'status'=>$d['status']??'want_to','data'=>json_encode(['data'=>$d['data']??[],'secret_gift_marker'=>$d['secret_gift_marker']??false,'created_by'=>$r->user()->id])]));return ApiResponse::created($this->decode(DB::table('shared_list_items')->where('id',$id)->first()));}

    private function deviceMigration(string $op,Request $r){if($op==='post_migrations_device_prepare'){$token='143-MIG-'.Str::upper(Str::random(32));$id=(string)Str::uuid();DB::table('device_migrations')->insert($this->row($r,['id'=>$id,'type'=>hash('sha256',$token),'status'=>'prepared','scheduled_at'=>now()->addMinutes(15),'data'=>json_encode(['from_device'=>$r->input('from_device')])]));return ApiResponse::created(['migration_id'=>$id,'transfer_token'=>$token,'qr_payload'=>'143://migration/'.$id.'?token='.urlencode($token),'expires_at'=>now()->addMinutes(15)]);}if($op==='post_migrations_device_confirm'){$d=$r->validate(['migration_id'=>'required|uuid','transfer_token'=>'required|string','new_device'=>'nullable|array']);$row=DB::table('device_migrations')->where('id',$d['migration_id'])->where('user_id',$r->user()->id)->where('status','prepared')->where('scheduled_at','>',now())->first();if(!$row||!hash_equals($row->type,hash('sha256',$d['transfer_token'])))return ApiResponse::problem('Invalid migration','Migration token is invalid or expired.',422,'invalid_migration');DB::table('device_migrations')->where('id',$row->id)->update(['status'=>'confirmed','completed_at'=>now(),'data'=>json_encode(['new_device'=>$d['new_device']??[]]),'updated_at'=>now()]);return ApiResponse::ok(['confirmed'=>true]);}$row=DB::table('device_migrations')->where('id',$r->route('migrationId'))->where('user_id',$r->user()->id)->first();return ApiResponse::ok($this->decode($row));}

    private function crud(string $table,Request $r){$space=RequestContext::coupleSpaceId($r);$id=null;foreach($r->route()->parameters() as $k=>$v)if(is_string($v)&&preg_match('/Id$/',$k))$id=$v;$q=DB::table($table)->whereNull('deleted_at')->where(function($x)use($r,$space){$x->where('user_id',$r->user()->id);if($space)$x->orWhere('couple_space_id',$space);});if($r->method()==='GET'){if($id)return ApiResponse::ok($this->decode((clone$q)->where('id',$id)->first()));return ApiResponse::ok($q->latest()->limit(min((int)$r->input('limit',50),100))->get()->map(fn($x)=>$this->decode($x)));}if($r->method()==='DELETE'){$q->where('id',$id)->update(['deleted_at'=>now(),'updated_at'=>now()]);return ApiResponse::ok(['deleted'=>true]);}if(in_array($r->method(),['PATCH','PUT'],true)){$old=$this->decode((clone$q)->where('id',$id)->first());if(!$old)return ApiResponse::problem('Not found','Resource does not exist.',404,'not_found');$data=array_replace_recursive($old['data']??[],$r->all());$q->where('id',$id)->update(['title'=>$r->input('title',$old['title']??null),'body'=>$r->input('body',$old['body']??null),'status'=>$r->input('status',$old['status']??'active'),'data'=>json_encode($data),'updated_at'=>now()]);return ApiResponse::ok($this->decode(DB::table($table)->where('id',$id)->first()));}$new=(string)Str::uuid();DB::table($table)->insert($this->row($r,['id'=>$new,'type'=>$r->input('type'),'title'=>$r->input('title'),'body'=>$r->input('body'),'status'=>$r->input('status','active'),'data'=>json_encode($r->all()),'scheduled_at'=>$r->input('scheduled_at')]));return ApiResponse::created($this->decode(DB::table($table)->where('id',$new)->first()));}
    private function upsertSetting(string $table,Request $r,array $data){$space=RequestContext::coupleSpaceId($r);$old=DB::table($table)->where('couple_space_id',$space)->whereNull('deleted_at')->first();if($old){DB::table($table)->where('id',$old->id)->update(['data'=>json_encode($data),'updated_at'=>now()]);$id=$old->id;}else{$id=(string)Str::uuid();DB::table($table)->insert($this->row($r,['id'=>$id,'type'=>'settings','data'=>json_encode($data)]));}return ApiResponse::ok($this->decode(DB::table($table)->where('id',$id)->first()));}
    private function row(Request $r,array $overrides=[]):array{return array_merge(['id'=>(string)Str::uuid(),'user_id'=>$r->user()?->id,'couple_space_id'=>RequestContext::coupleSpaceId($r),'parent_id'=>null,'type'=>null,'status'=>'active','title'=>null,'body'=>null,'data'=>json_encode([]),'metadata'=>json_encode([]),'scheduled_at'=>null,'occurred_at'=>now(),'completed_at'=>null,'created_at'=>now(),'updated_at'=>now(),'deleted_at'=>null],$overrides);}
    private function decode($row){if(!$row)return null;$x=(array)$row;foreach(['data','metadata']as$k)if(isset($x[$k])&&is_string($x[$k]))$x[$k]=json_decode($x[$k],true)??$x[$k];return $x;}
}
